    "WOTSPublicKey",
    "keygen",
    "merkle_verify",
    "message_bits",
    "message_digest",
    "public_key_from",
    "sign",
    "verify",
    "wots_keygen",
    "wots_sign",
    "wots_verify",
]

BITS = 256
HASH_BYTES = 32
_DOMAIN = b"pqattest/lamport/v1"


